test.query:
${CLICKHOUSE_CLIENT} --query "
    TRUNCATE TABLE merge_dst;
    ALTER TABLE merge_dst ATTACH PARTITION tuple() FROM merge_src;
    OPTIMIZE TABLE merge_dst FINAL SETTINGS optimize_throw_if_noop = 1;
"

${CLICKHOUSE_CLIENT} --query "
    TRUNCATE TABLE merge_dst_batch;
    ALTER TABLE merge_dst_batch ATTACH PARTITION tuple() FROM merge_src;
    OPTIMIZE TABLE merge_dst_batch FINAL SETTINGS optimize_throw_if_noop = 1;
"

${CLICKHOUSE_CLIENT} --query "
    TRUNCATE TABLE merge_dst_str;
    ALTER TABLE merge_dst_str ATTACH PARTITION tuple() FROM merge_src_str;
    OPTIMIZE TABLE merge_dst_str FINAL SETTINGS optimize_throw_if_noop = 1;
"
